Here's a function that simulates the pours and validates each step:

```python
def verify_steps(capacities, initial, steps, goal=None):
    """
    Verify a sequence of water-jug pouring steps.

    capacities : dict[str, int]   e.g. {"12": 12, "8": 8, "5": 5}
    initial    : dict[str, int]   starting amounts
    steps      : list[tuple]      each is (source, dest) = "pour source into dest"
    goal       : dict[str, int]   optional {container: target} to check at end

    Returns (ok: bool, final_state: dict, message: str)
    """
    state = dict(initial)

    if set(state) != set(capacities):
        return False, state, "initial and capacities must name the same containers"
    for name, amt in state.items():
        if not 0 <= amt <= capacities[name]:
            return False, state, f"initial amount {amt} in '{name}' is out of range"

    for i, (src, dst) in enumerate(steps):
        if src not in capacities or dst not in capacities:
            return False, state, f"step {i}: unknown container"
        if src == dst:
            return False, state, f"step {i}: can't pour '{src}' into itself"
        if state[src] == 0:
            return False, state, f"step {i}: '{src}' is empty"
        if state[dst] >= capacities[dst]:
            return False, state, f"step {i}: '{dst}' is already full"

        pour = min(state[src], capacities[dst] - state[dst])  # fill dest or empty src
        state[src] -= pour
        state[dst] += pour

    if goal is not None:
        for name, amt in goal.items():
            if state.get(name, 0) != amt:
                return False, state, f"goal not met: '{name}' has {state.get(name)}, want {amt}"

    return True, state, "all steps valid"
```

**Usage with the 6-liter solution:**

```python
caps = {"12": 12, "8": 8, "5": 5}
start = {"12": 12, "8": 0, "5": 0}
steps = [("12","8"), ("8","5"), ("5","12"), ("8","5"), ("12","8"), ("8","5")]

ok, final, msg = verify_steps(caps, start, steps, goal={"8": 6})
print(ok, final, msg)
# True {'12': 1, '8': 6, '5': 5} all steps valid
```

It checks that every container exists, the source isn't empty, the destination isn't full, and (optionally) that the final state matches your goal.
